#include <bits/stdc++.h>
using namespace std;

using ll = long long;
constexpr ll mod = 1000000007LL;

void mod_sum(ll& a, ll b) {
    a = (a + b) % mod;
}

int global_n;

struct Mtx {
    ll entry[33][33];

    Mtx() {
        memset(entry, 0, sizeof(entry));
    }

    void set_unit() {
        memset(entry, 0, sizeof(entry));
        for (int i = 0; i < global_n; ++i) entry[i][i] = 1;
    }

    Mtx operator*(const Mtx& other) const {
        Mtx res;
        for (int i = 0; i < global_n; ++i) {
            for (int j = 0; j < global_n; ++j) {
                for (int k = 0; k < global_n; ++k) {
                    mod_sum(res.entry[i][j], entry[i][k] * other.entry[k][j]);
                }
            }
        }
        return res;
    }
};

ll input_n, input_k;
Mtx unary_base[70];
Mtx binary_combined[70];
Mtx row_movements[70];
Mtx col_movements[70];

int run() {
    ios::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> input_n >> input_k;
    global_n = input_k + 1;

    // Initialize unary operation matrices
    for (int i = 0; i <= input_k; ++i) {
        unary_base[i].set_unit();
        if (i > 0) {
            for (int j = 0; j <= input_k; ++j) {
                unary_base[i].entry[i][j] = 1;
            }
        }
    }

    // Row movement matrices
    for (int i = 0; i <= input_k; ++i) {
        row_movements[i].set_unit();
        if (i == 1) {
            memset(row_movements[i].entry, 0, sizeof(row_movements[i].entry));
            row_movements[i].entry[0][0] = 1;
            row_movements[i].entry[1][input_k] = 1;
            for (int j = 2; j <= input_k; ++j) {
                row_movements[i].entry[j][j-1] = 1;
            }
        } else if (i > 1) {
            row_movements[i] = row_movements[1] * row_movements[i-1];
        }
    }

    // Column movement matrices
    for (int i = 0; i <= input_k; ++i) {
        col_movements[i].set_unit();
        if (i == 1) {
            memset(col_movements[i].entry, 0, sizeof(col_movements[i].entry));
            col_movements[i].entry[0][0] = 1;
            col_movements[i].entry[input_k][1] = 1;
            for (int j = 2; j <= input_k; ++j) {
                col_movements[i].entry[j-1][j] = 1;
            }
        } else if (i > 1) {
            col_movements[i] = col_movements[i-1] * col_movements[1];
        }
    }

    // Base binary combined matrix
    binary_combined[1].set_unit();
    for (int i = 1; i <= input_k; ++i) {
        binary_combined[1] = unary_base[i] * binary_combined[1];
    }

    // Convert n to base K representation
    vector<int> digits;
    ll temp = input_n;
    while (temp > 0) {
        digits.push_back(temp % input_k);
        temp /= input_k;
    }
    reverse(digits.begin(), digits.end());

    // Build higher level combined matrices
    for (int level = 2; level <= (int)digits.size(); ++level) {
        binary_combined[level].set_unit();
        for (int idx = 0; idx < input_k; ++idx) {
            binary_combined[level] = row_movements[idx] * binary_combined[level-1] * col_movements[idx] * binary_combined[level];
        }
    }

    // Accumulate result
    Mtx result;
    result.set_unit();
    int current_idx = 0;

    for (int i = 0; i < (int)digits.size(); ++i) {
        if (i == (int)digits.size() - 1) {
            for (int j = 0; j < digits[i]; ++j) {
                result = unary_base[current_idx % input_k + 1] * result;
                ++current_idx;
            }
        } else {
            for (int j = 0; j < digits[i]; ++j) {
                result = row_movements[current_idx % input_k] * binary_combined[digits.size() - i - 1] * col_movements[current_idx % input_k] * result;
                ++current_idx;
            }
        }
    }

    ll ans = 1;
    for (int i = 1; i <= input_k; ++i) {
        mod_sum(ans, result.entry[i][0]);
    }

    cout << ans << '\n';
    return 0;
}

int main() {
    return run();
}
